function readStoredJson(key, fallback) {
  try {
    const raw = localStorage.getItem(key);
    if (!raw) return fallback;
    return JSON.parse(raw);
  } catch (error) {
    console.warn(`Ignoring damaged browser storage for ${key}`, error);
    return fallback;
  }
}

function writeStoredJson(key, value) {
  try {
    localStorage.setItem(key, JSON.stringify(value));
    return true;
  } catch (error) {
    console.warn(`Unable to save browser storage for ${key}`, error);
    const syncState = document.querySelector("#syncState");
    if (syncState) {
      syncState.textContent = "Browser storage is full or blocked. PC folder save is still attempted.";
    }
    return false;
  }
}

